  customer ecommerce_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([customer_id, expires_at], map: "ecommerce_mall_customer_password_resets_customer_id_ex_20362154")
}

/// Email verification tokens for customer registration and email address
/// changes. This table stores temporary tokens that customers must confirm
/// to verify their email ownership during account creation or when updating
/// their email address. Each customer can have multiple pending
/// verifications (e.g., for email changes), but only one active verification
/// at a time. Tokens expire after a short period for security. The
/// customer_id references the customer who initiated the verification, and
/// the email field stores the target email being verified. This enables the
/// system to send verification emails and validate that customers control
/// the email addresses they claim to own.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_customer_email_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link ecommerce_mall_customers.id}. The customer who
  /// initiated this email verification request.
  customer_id String @db.Uuid

  /// The email address being verified for ownership.
  email String

  /// Secure random verification token sent via email.
  token String

  /// Type of verification: 'registration' for initial registration,
  /// 'email_change' for email address updates.
  token_type String

  /// Token expiration timestamp - tokens expire after 24 hours for security.
  expires_at DateTime @db.Timestamptz

  /// Whether this token has been successfully used for verification.
  is_used Boolean

  /// Creation timestamp of this email verification record.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of this email verification record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for audit trail.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer ecommerce_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([customer_id, token], map: "ecommerce_mall_customer_email_verifications_customer_i_57461fd8")
  @@index([email])
  // spellchecker: ignore-next-line
  @@index([customer_id, created_at], map: "ecommerce_mall_customer_email_verifications_customer_i_1fa9832f")
  @@index([expires_at])
}

