/// Customer purchase transactions representing complete orders with status
/// tracking and financial totals.
///
/// An order is created when a customer completes the checkout process after
/// successful payment processing through an external payment gateway. Each
/// order is permanently associated with exactly one customer who created it
/// and contains one or more order items from one or more sellers.
///
/// Key relationships:
/// - Belongs to a customer via {@link ecommerce_mall_customers.id} -
/// customers can view all their orders in order history
/// - Contains many order items (managed in ecommerce_mall_order_items table)
/// - each item represents a specific product variant purchase
/// - References shipping address via {@link ecommerce_mall_addresses.id} -
/// the delivery location selected at checkout
/// - Contains many shipments (managed in ecommerce_mall_shipments table) -
/// physical delivery of items
///
/// The overall order status is automatically derived from the statuses of
/// all order items within the order per section 136. If all items are paid,
/// order is paid; if any item shipped, order is shipped; if all items
/// delivered, order is delivered; if all items cancelled or refunded, order
/// reflects that status; if mixed item statuses, order is partially
/// completed.
///
/// Order creation is irreversible - once created, the order cannot be
/// modified or cancelled by the customer. Orders become immediately visible
/// to relevant sellers for fulfillment. Customer can cancel or refund
/// individual items within the order (section 142-143), not the entire
/// order.
///
/// Each order is assigned a unique order number at creation for
/// identification, customer reference, and support inquiries (section 129).
/// The order number is included in order confirmations and is visible to the
/// customer and relevant sellers.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer who created this order. {@link ecommerce_mall_customers.id}
  customer_id String @db.Uuid

  /// Shipping address selected at checkout. {@link ecommerce_mall_addresses.id}
  shipping_address_id String @db.Uuid

  /// Unique order number for identification and reference. Generated at order
  /// creation.
  order_number String

  /// Total price of the order (sum of all order item prices).
  total_price Float @db.DoublePrecision

  /// Overall order status derived from item statuses: paid, shipped,
  /// delivered, cancelled, refunded, or partially_completed.
  status String

  /// Date and time when the order was successfully created.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp when any order field was modified.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if order is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  customer        ecommerce_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  shippingAddress ecommerce_mall_addresses @relation(fields: [shipping_address_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  inventoryRecords ecommerce_mall_inventory_records[]
  orderItems       ecommerce_mall_order_items[]
  snapshots        ecommerce_mall_order_snapshots[]
  shipments        ecommerce_mall_shipments[]
  reviews          ecommerce_mall_reviews[]

  @@unique([order_number])
  //----
  // INDEXES
  //----
  @@index([shipping_address_id])
  @@index([customer_id, created_at])
}

/// Order line items representing individual products purchased within an order.
///
/// This table captures immutable historical data at order time, including
/// snapshot references to the product, variant, and seller as they existed
/// when the order was placed. Each order item tracks quantity, unit price,
/// and total price at purchase time.
///
/// Business Context:
/// - Order items form the bridge between orders and products
/// - Support order cancellations via {@link
/// ecommerce_mall_cancellation_requests}
/// - Support refunds via {@link ecommerce_mall_refund_requests}
/// - Reference product variants in {@link ecommerce_mall_product_variants}
/// through snapshot references
/// - Linked to shipments in {@link ecommerce_mall_shipments} via junction table
/// - Enable historical reporting of what was actually purchased
///
/// Key Relationships:
/// - Belongs to one {@link ecommerce_mall_orders} parent order
/// - References product snapshot in {@link ecommerce_mall_snapshots} for
/// immutable product state
/// - References product variant snapshot in {@link ecommerce_mall_snapshots}
/// for immutable variant state
/// - References seller snapshot in {@link ecommerce_mall_snapshots} for
/// immutable seller state at order time
///
/// Stance: primary - Order items require independent management for customer
/// order history, seller sales reports, cancellation processing, refund
/// processing, and shipment fulfillment. Users need to search/filter order
/// items independently across their orders.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged order's {@link ecommerce_mall_orders.id}. Each order item is
  /// part of exactly one order.
  ecommerce_mall_order_id String @db.Uuid

  /// Product snapshot's {@link ecommerce_mall_snapshots.id}. Captures product
  /// state (name, description, base price) at order time for immutable order
  /// history.
  product_snapshot_id String @db.Uuid

  /// Product variant snapshot's {@link ecommerce_mall_snapshots.id}. Captures
  /// variant state (SKU, specific price, specific stock) at order time for
  /// immutable order history.
  variant_snapshot_id String @db.Uuid

  /// Seller snapshot's {@link ecommerce_mall_snapshots.id}. Captures seller
  /// information at order time for immutable order history, enabling disputes
  /// to reference seller as they were.
  seller_snapshot_id String @db.Uuid

  /// Product name at time of purchase. Denormalized from snapshot for
  /// immutable order history - never changes even if product is renamed.
  product_name String

  /// Product variant SKU at time of purchase. Denormalized from snapshot for
  /// immutable order history.
  product_sku String

  /// Variant name/description at time of purchase. Captures the specific
  /// variant option selected (e.g., 'Red, Large').
  variant_name String

  /// Number of units purchased. Must be positive integer. Used to calculate
  /// total_price and for inventory deduction.
  quantity Int @db.Integer

  /// Price per unit at time of purchase in USD. Denormalized from variant
  /// snapshot for immutable order history. Reflects price at order time, not
  /// current product price.
  unit_price Float @db.DoublePrecision

  /// Total price for this line item (quantity × unit_price) at time of
  /// purchase in USD. Calculated field denormalized for order totals.
  total_price Float @db.DoublePrecision

  /// Timestamp when this order item was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this order item was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. NULL when active, set when logically deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  order           ecommerce_mall_orders    @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  productSnapshot ecommerce_mall_snapshots @relation("ecommerce_mall_order_items_of_product_snapshot_id", fields: [product_snapshot_id], references: [id], onDelete: Cascade)
  variantSnapshot ecommerce_mall_snapshots @relation("ecommerce_mall_order_items_of_variant_snapshot_id", fields: [variant_snapshot_id], references: [id], onDelete: Cascade)
  sellerSnapshot  ecommerce_mall_snapshots @relation("ecommerce_mall_order_items_of_seller_snapshot_id", fields: [seller_snapshot_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots            ecommerce_mall_order_item_snapshots[]
  shipmentItems        ecommerce_mall_shipments_order_items[]
  cancellationRequests ecommerce_mall_cancellation_requests[]
  refundRequests       ecommerce_mall_refund_requests[]

  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_order_id, variant_snapshot_id], map: "ecommerce_mall_order_items_ecommerce_mall_order_id_var_553d175b")
  //----
  // INDEXES
  //----
  @@index([variant_snapshot_id])
  @@index([seller_snapshot_id])
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_order_id, created_at], map: "ecommerce_mall_order_items_ecommerce_mall_order_id_cre_a44064e3")
  @@index([product_snapshot_id])
}

/// Point-in-time snapshots of orders capturing complete transaction state at
/// creation and modification.
///
/// This table implements the snapshot pattern to preserve historical order
/// states for audit trails, dispute resolution, and historical reporting.
/// Each snapshot contains a full denormalized copy of the order's data at a
/// specific point in time, enabling read-back of historical states without
/// accessing the current order data.
///
/// Key relationships:
/// - References {@link ecommerce_mall_orders} - the parent order being tracked
/// - Each order can have multiple snapshots as it transitions through states
/// (pending, confirmed, shipped, completed, cancelled)
/// - Used for: dispute resolution, historical reporting, audit compliance,
/// rollback capabilities
///
/// Behavioral notes:
/// - Append-only table (rarely modified or deleted)
/// - Denormalized structure captures order data as it existed at snapshot time
/// - Useful for tracking order number changes, amount recalculations, status
/// transitions
/// - Complements the central {@link ecommerce_mall_snapshots} table which
/// tracks cross-domain state changes
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_order_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent order's {@link ecommerce_mall_orders.id}. Reference to the order
  /// this snapshot belongs to.
  ecommerce_mall_order_id String @db.Uuid

  /// Customer who placed the order {@link ecommerce_mall_customers.id}.
  /// Denormalized for historical accuracy.
  customer_id String @db.Uuid

  /// Seller who owns the products in this order {@link
  /// ecommerce_mall_sellers.id}. Denormalized for historical accuracy.
  seller_id String @db.Uuid

  /// Unique order number identifier. May change over time but snapshot
  /// preserves the value at snapshot time.
  order_number String

  /// Order status at snapshot time (pending, confirmed, shipped, completed,
  /// cancelled).
  status String

  /// Number of items in this order at snapshot time.
  items_count Int @db.Integer

  /// Total order amount including all items, shipping, and discounts.
  total_amount Float @db.DoublePrecision

  /// Amount paid by customer at snapshot time.
  paid_amount Float @db.DoublePrecision

  /// Total refund amount for this order at snapshot time.
  refund_amount Float @db.DoublePrecision

  /// Shipping cost for this order at snapshot time.
  shipping_cost Float @db.DoublePrecision

  /// Total discount applied to this order at snapshot time.
  discount_amount Float @db.DoublePrecision

  /// Payment method used for this order (credit_card, bank_transfer, etc.).
  payment_method String

  /// Payment status at snapshot time (pending, paid, failed, refunded).
  payment_status String

  /// Customer name at snapshot time. Denormalized for historical accuracy.
  customer_name String

  /// Customer email at snapshot time. Denormalized for historical accuracy.
  customer_email String

  /// Shipping address as string at snapshot time. Denormalized for historical
  /// accuracy.
  shipping_address String

  /// Shipping city at snapshot time. Denormalized for historical accuracy.
  shipping_city String

  /// Shipping state at snapshot time. Denormalized for historical accuracy.
  shipping_state String

  /// Shipping postal code at snapshot time. Denormalized for historical
  /// accuracy.
  shipping_postal_code String

  /// Shipping country at snapshot time. Denormalized for historical accuracy.
  shipping_country String

  /// Timestamp when this snapshot was created.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  order    ecommerce_mall_orders    @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  customer ecommerce_mall_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  seller   ecommerce_mall_sellers   @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([customer_id])
  @@index([seller_id])
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_order_id, created_at], map: "ecommerce_mall_order_snapshots_ecommerce_mall_order_id_f99fa9db")
}

/// Immutable snapshot table capturing point-in-time state of order items for
/// audit trail and historical reference.
///
/// This table records changes to order items (ecommerce_mall_order_items) as
/// they occur, preserving the before and after values of modified fields.
/// Each snapshot represents a specific moment in the order item's lifecycle
/// and is never modified or deleted.
///
/// Key relationships:
/// - {@link EcommerceMallOrderItemSnapshot.orderItem} - References the order
/// item being captured
/// - {@link EcommerceMallOrderItemSnapshot.actorType} + {@link
/// EcommerceMallOrderItemSnapshot.actorId} - Identifies which actor made the
/// change (customer, seller, or admin)
///
/// Use cases:
/// - Dispute resolution: View what the order item looked like at any point
/// in time
/// - Audit compliance: Track who changed what and when
/// - Historical analysis: Analyze order item modifications across the platform
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_order_item_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order item this snapshot belongs to. {@link EcommerceMallOrderItem.id}
  order_item_id String @db.Uuid

  /// Type of actor who made the change (customer, seller, admin). Used with
  /// actor_id to identify the actor.
  actor_type String

  /// ID of the actor who made the change (references appropriate actor table
  /// based on actor_type).
  actor_id String @db.Uuid

  /// JSON representation of order item state before the change. Captures
  /// original values for audit comparison.
  before_data String

  /// JSON representation of order item state after the change. Captures new
  /// values for audit trail.
  after_data String

  /// Optional reason for the change when provided by the actor.
  change_reason String?

  /// Timestamp when this snapshot was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this snapshot was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for data retention and archival.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  orderItem ecommerce_mall_order_items @relation(fields: [order_item_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([order_item_id, created_at], map: "ecommerce_mall_order_item_snapshots_order_item_id_crea_ce456eaa")
}

schemas.schema-05-shipments.prisma:
/// Main shipment entity tracking physical delivery logistics for order
/// fulfillment.
///
/// This table represents shipments that coordinate the delivery of order
/// items from sellers to customers. Each shipment is associated with an
/// order and fulfilled by a seller. The table tracks carrier information
/// (carrier name, phone, website), and delivery status throughout the
/// shipping lifecycle.
///
/// Shipments are managed by sellers (who create them when fulfilling orders)
/// and admins (who monitor logistics performance). Customers can track their
/// shipments via tracking codes stored in the associated tracking codes
/// table.
///
/// Related entities:
/// - {@link ecommerce_mall_orders} - The order being shipped (one order may
/// have multiple shipments if items ship separately)
/// - {@link ecommerce_mall_sellers} - The seller fulfilling the shipment
/// - {@link ecommerce_mall_shipment_tracking_codes} - Child table storing
/// multiple carrier tracking codes per shipment (replaces comma-separated
/// tracking_numbers)
/// - {@link ecommerce_mall_shipment_snapshots} - Audit trail for shipment
/// state changes
///
/// Key fields:
/// - carrier_name, carrier_phone, carrier_website: Single carrier reference
/// (the primary carrier for this shipment)
/// - status: Current delivery lifecycle state
/// - shipped_at, delivered_at, estimated_delivery_at: Temporal tracking for
/// delivery milestones
///
/// @namespace Shipments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The order being shipped. {@link ecommerce_mall_orders.id}
  ecommerce_mall_order_id String @db.Uuid

  /// The seller fulfilling this shipment. {@link ecommerce_mall_sellers.id}
  ecommerce_mall_seller_id String @db.Uuid

  /// Primary shipping carrier name (e.g., FedEx, UPS, DHL).
  carrier_name String?

  /// Carrier customer service phone number.
  carrier_phone String?

  /// Carrier's official website URL for tracking.
  carrier_website String? @db.VarChar(80000)

  /// Current delivery status: pending, in-transit, delivered, failed,
  /// cancelled.
  status String

  /// When the shipment was marked as shipped (carrier pickup or dispatch).
  shipped_at DateTime? @db.Timestamptz

  /// When the shipment was successfully delivered to customer.
  delivered_at DateTime? @db.Timestamptz

  /// Estimated delivery date provided by carrier.
  estimated_delivery_at DateTime? @db.Timestamptz

  /// Final delivery address for this shipment.
  delivery_address String?

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for order cancellations or returns.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  order  ecommerce_mall_orders  @relation(fields: [ecommerce_mall_order_id], references: [id], onDelete: Cascade)
  seller ecommerce_mall_sellers @relation(fields: [ecommerce_mall_seller_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  orderItems      ecommerce_mall_shipments_order_items[]
  snapshots       ecommerce_mall_shipment_snapshots[]
  trackingUpdates ecommerce_mall_shipment_tracking_updates[]
  trackingCodes   ecommerce_mall_shipment_tracking_codes[]

  //----
  // INDEXES
  //----
  @@index([ecommerce_mall_order_id, status])
  @@index([ecommerce_mall_seller_id, status])
  @@index([status])
}

/// Junction table linking shipments to order items for fulfillment tracking.
///
/// This table represents the many-to-many relationship between shipments and
/// order items, recording which order items are included in each shipment
/// and the quantity shipped. A shipment can contain multiple order items
/// from the same seller, and an order item may be split across multiple
/// shipments if partial fulfillment is required.
///
/// Business purpose:
/// - Tracks order item fulfillment within shipments
/// - Records shipped quantity (may differ from original order quantity for
/// partial shipments)
/// - Enables query for all order items in a shipment or all shipments
/// containing a specific order item
/// - Supports inventory deduction and tracking workflows
///
/// Relationships:
/// - BelongsTo {@link ecommerce_mall_shipments} - Each line item is part of
/// one shipment
/// - BelongsTo {@link ecommerce_mall_order_items} - Each line item
/// references the original order item being fulfilled
///
/// Managed through parent entities: Users do not independently create or
/// delete records; they are automatically generated during shipment creation
/// and fulfillment processes.
///
/// @namespace Shipments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipments_order_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Shipment's {@link ecommerce_mall_shipments.id} that contains this order
  /// item.
  ecommerce_mall_shipment_id String @db.Uuid

  /// Order item's {@link ecommerce_mall_order_items.id} being fulfilled in
  /// this shipment.
  ecommerce_mall_order_item_id String @db.Uuid

  /// Quantity of this order item being shipped. May differ from original order
  /// quantity if partial shipment.
  shipped_quantity Int @db.Integer

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (null if active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  shipment  ecommerce_mall_shipments   @relation(fields: [ecommerce_mall_shipment_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_shipments_order_items_ecommerce_mall_sh_080b4fa0")
  // spellchecker: ignore-next-line
  orderItem ecommerce_mall_order_items @relation(fields: [ecommerce_mall_order_item_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_shipments_order_items_ecommerce_mall_or_71b368de")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@unique([ecommerce_mall_shipment_id, ecommerce_mall_order_item_id], map: "ecommerce_mall_shipments_order_items_ecommerce_mall_sh_6f158bef")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_shipment_id], map: "ecommerce_mall_shipments_order_items_ecommerce_mall_sh_3b3bf821")
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_order_item_id], map: "ecommerce_mall_shipments_order_items_ecommerce_mall_or_2c8712d1")
}

/// Audit trail snapshots capturing point-in-time state of shipments for
/// dispute resolution and historical reference.
///
/// Each snapshot records the complete state of a shipment at a specific
/// moment, including carrier information, tracking details, status, and
/// timestamps. Snapshots are immutable historical records used for:
///
/// - Dispute resolution: Verify shipment state at specific points in time
/// - Audit trail: Track all state changes and tracking updates
/// - Historical analysis: Analyze shipment lifecycle patterns
/// - Regulatory compliance: Maintain permanent records of delivery status
///
/// References the parent {@link ecommerce_mall_shipments} entity and
/// indirectly references {@link ecommerce_mall_orders} and {@link
/// ecommerce_mall_sellers} through the shipment relationship.
///
/// @namespace Shipments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipment_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged shipment's {@link ecommerce_mall_shipments.id}
  ecommerce_mall_shipment_id String @db.Uuid

  /// Carrier-assigned tracking number for package identification
  tracking_number String

  /// Name of the shipping carrier (e.g., FedEx, UPS, DHL)
  carrier_name String?

  /// Carrier customer service contact information or website
  carrier_contact String? @db.VarChar(80000)

  /// Current shipment status (pending, in transit, out for delivery,
  /// delivered, exception, returned)
  status String

  /// Originally estimated delivery date
  estimated_delivery_date DateTime? @db.Timestamptz

  /// Actual delivery completion timestamp (null if not delivered)
  actual_delivery_date DateTime? @db.Timestamptz

  /// Date and time when package was handed to carrier
  shipped_date DateTime? @db.Timestamptz

  /// URL for tracking package status with carrier
  tracking_url String? @db.VarChar(80000)

  /// Shipping service level (standard, express, overnight, economy)
  shipping_method String?

  /// Package weight in kilograms
  weight_kg Float? @db.DoublePrecision

  /// Package length in centimeters
  dimensions_length_cm Float? @db.DoublePrecision

  /// Package width in centimeters
  dimensions_width_cm Float? @db.DoublePrecision

  /// Package height in centimeters
  dimensions_height_cm Float? @db.DoublePrecision

  /// Complete delivery address including recipient name, street, city, state,
  /// postal code, country
  delivery_address String?

  /// Whether signature was required for delivery
  signature_required Boolean?

  /// Whether a signature was actually obtained for delivery
  signature_obtained Boolean?

  /// Delivery notes such as 'Left at front door', 'Signed by recipient', etc.
  delivery_notes String?

  /// Description of any delivery exception (weather delay, address issue,
  /// failed delivery attempt)
  exception_description String?

  /// Timestamp when this snapshot was created
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  shipment ecommerce_mall_shipments @relation(fields: [ecommerce_mall_shipment_id], references: [id], onDelete: Cascade, map: "ecommerce_mall_shipment_snapshots_ecommerce_mall_shipm_e1405aef")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([ecommerce_mall_shipment_id, created_at], map: "ecommerce_mall_shipment_snapshots_ecommerce_mall_shipm_79a73276")
  @@index([status])
  @@index([actual_delivery_date])
  @@index([tracking_number(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([delivery_address(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Carrier tracking status updates for shipment delivery lifecycle tracking.
///
/// This subsidiary table records all tracking status changes pushed by
/// carriers or shipping systems. Each update represents a state transition
/// in the shipment's delivery journey (pending → in_transit →
/// out_for_delivery → delivered).
///
/// Relationships:
/// - Belongs to {@link ecommerce_mall_shipments} - one shipment has many
/// tracking updates
/// - Used by customers and sellers to monitor delivery progress
/// - Read-only from user perspective - automatically created by carrier API
/// integration
///
/// Temporal fields:
/// - created_at: when tracking update was recorded
/// - updated_at: last modification timestamp (for consistency)
/// - deleted_at: soft delete (optional)
///
/// @namespace Shipments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_mall_shipment_tracking_updates {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Shipment's {@link ecommerce_mall_shipments.id} this tracking update
  /// belongs to.
  shipment_id String @db.Uuid

  /// Current tracking status from carrier (pending, in_transit,
  /// out_for_delivery, delivered, failed, exception).
  tracking_status String

  /// JSON payload from carrier API containing full tracking event data. Stored
  /// as string due to external-integration feature requirement.
  carrier_response String?

  /// When this tracking update was recorded.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (nullable for active records).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  shipment ecommerce_mall_shipments @relation(fields: [shipment_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([shipment_id, created_at], map: "ecommerce_mall_shipment_tracking_updates_shipment_id_c_4c29663c")
}

/// Child table storing multiple carrier tracking codes per shipment.
///
