  const slugSortResponse =
    await api.functional.ecommerceMall.admin.categories.snapshots.index(
      adminConnection,
      {
        categoryId,
        body: {
          page: 1,
          limit: 5,
          sort: "slug",
        } satisfies IEcommerceMallCategorySnapshot.IRequest,
      },
    );
