  TestValidator.equals(
    "category sort pagination records",
    categorySortResponse.pagination.records,
    createdAtSortResponse.pagination.records,
  );
  TestValidator.equals(
    "slug sort pagination records",
    slugSortResponse.pagination.records,
    createdAtSortResponse.pagination.records,
  );
}

