  const page2Limit10 =
    await api.functional.ecommerceMall.customer.orders.snapshots.index(
      customerConnection,
      {
        orderId: testOrderId,
        body: {
          page: 2,
          limit: 10,
        } satisfies IEcommerceMallOrderSnapshot.IRequest,
      },
    );
