export async function test_api_review_helpfulness_vote_update(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer setup - join and create isolated connection
  const customerConnection: api.IConnection = { host: connection.host };
  const customer: IEcommerceMallCustomer.IAuthorized =
    await authorize_customer_join(customerConnection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IEcommerceMallCustomer.IJoin,
    });
  typia.assert(customer);
  // Create new connection with customer's authorization token
  const authenticatedCustomerConnection: api.IConnection = {
    host: connection.host,
    headers: { Authorization: customer.token.access },
  };
  // 2. Create a review for the customer to vote on
  const review: IEcommerceMallReview =
    await generate_random_ecommerce_mall_customer_reviews_create(
      authenticatedCustomerConnection,
      {},
    );
  typia.assert(review);
  // 3. Cast initial helpfulness vote (helpful=true)
  const initialVote: IEcommerceMallReviewHelpfulnessVote =
    await api.functional.ecommerceMall.reviews.helpfulness_votes.updateHelpfulnessVote(
      authenticatedCustomerConnection,
      {
        reviewId: review.id,
        body: {
          helpfulness: true,
        } satisfies IEcommerceMallReviewHelpfulnessVote.IUpdate,
      },
    );
  typia.assert(initialVote);
  // 4. Update the helpfulness vote (helpfulness=false)
  const updatedVote: IEcommerceMallReviewHelpfulnessVote =
    await api.functional.ecommerceMall.reviews.helpfulness_votes.updateHelpfulnessVote(
      authenticatedCustomerConnection,
      {
        reviewId: review.id,
        body: {
          helpfulness: false,
        } satisfies IEcommerceMallReviewHelpfulnessVote.IUpdate,
      },
    );
  typia.assert(updatedVote);
