  TestValidator.equals(
    "vote ID should remain same after update",
    initialVote.id,
    updatedVote.id,
  );
  TestValidator.equals(
    "vote should be updated to not helpful",
    updatedVote.helpfulness,
    false,
  );
  TestValidator.notEquals(
    "updated_at should be different after update",
    initialVote.updated_at,
    updatedVote.updated_at,
  );
  TestValidator.equals(
    "vote should reference correct customer",
    updatedVote.customer.id,
    customer.id,
  );
  TestValidator.equals(
    "vote should reference correct review",
    updatedVote.review.id,
    review.id,
  );
}

