    snapshot.old_data,
    null,
  );
  TestValidator.notEquals("new_data is not empty", snapshot.new_data, "");
  TestValidator.predicate(
    "snapshot has valid timestamp",
    snapshot.created_at !== undefined && snapshot.created_at.length > 0,
  );
