  const addressAId: string & tags.Format<"uuid"> = addressA.id;
  TestValidator.equals(
    "Address A should be default",
    addressA.is_default,
    true,
  );
  // 3. Create Address B (A remains default)
  const addressB =
    await generate_random_ecommerce_mall_customer_addresses_create(
      customerConnection,
