    await api.functional.ecommerceMall.superAdmin.refund_requests.snapshots.index(
      superAdminConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          action_type: "approved" as const,
          limit: 50 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
