export async function test_api_seller_product_image_reorder_thumbnail_change(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller: IEcommerceMallSeller.IAuthorized = await authorize_seller_join(
    sellerConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "TestPass123!",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      },
    },
  );
  typia.assert(seller);
  // 2. Create a product for the seller
  const product: IEcommerceMallProduct =
    await generate_random_ecommerce_mall_seller_products_create(
      sellerConnection,
      {
        body: {
          name: RandomGenerator.paragraph({ sentences: 3 }),
          description: RandomGenerator.paragraph({ sentences: 5 }),
          category_id: typia.random<string & tags.Format<"uuid">>(),
          base_price: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
        },
      },
    );
  typia.assert(product);
  // 3. Upload 3 images with display_order 0, 1, 2
  const images: IEcommerceMallProductImage[] = await Promise.all(
    ArrayUtil.repeat(3, (index) =>
      generate_random_ecommerce_mall_seller_products_images_create(
        sellerConnection,
        {
          body: {
            image_url: typia.random<string & tags.MaxLength<80000>>(),
            display_order: index,
            alt_text: RandomGenerator.name(),
          },
          params: { productId: product.id },
        },
      ),
    ),
  );
  typia.assert(images);
  // Store image URLs before reordering
  const originalFirstImageUrl: string = images[0].image_url;
  const secondImageUrl: string = images[1].image_url;
  const thirdImageUrl: string = images[2].image_url;
  // 4. Create reorder request - move image at index 2 to position 0
  const reorderBody: IEcommerceMallProductImage.IReorder = {
    images: [
      {
        image_id: images[2].id,
        display_order: 0,
      },
      {
        image_id: images[0].id,
        display_order: 1,
      },
      {
        image_id: images[1].id,
        display_order: 2,
      },
    ],
  } satisfies IEcommerceMallProductImage.IReorder;
  // 5. Execute reorder operation
  const reorderResponse: IPageIEcommerceMallProductImage.ISummary =
    await api.functional.ecommerceMall.seller.products.images.reorder.patchByProductid(
      sellerConnection,
      {
        productId: product.id,
        body: reorderBody,
      },
    );
  typia.assert(reorderResponse);
  // 6. Validate response contains 3 images
  TestValidator.equals(
    "image count after reorder",
    reorderResponse.data.length,
    3,
  );
  // 7. Verify the new thumbnail (was at index 2, now at position 0)
  const newThumbnail: IEcommerceMallProductImage.ISummary | undefined =
    reorderResponse.data.find((img) => img.display_order === 0);
  TestValidator.notEquals(
    "new thumbnail is the moved image",
    newThumbnail?.image_url,
    originalFirstImageUrl,
  );
  TestValidator.equals(
    "new thumbnail is the third uploaded image",
    newThumbnail?.image_url,
    thirdImageUrl,
  );
  // 8. Verify previous main image is now at position 1
  const oldThumbnail: IEcommerceMallProductImage.ISummary | undefined =
    reorderResponse.data.find((img) => img.display_order === 1);
  TestValidator.equals(
    "old thumbnail is now at position 1",
    oldThumbnail?.image_url,
    originalFirstImageUrl,
  );
  // 9. Verify second image is now at position 2
  const secondImageNow: IEcommerceMallProductImage.ISummary | undefined =
    reorderResponse.data.find((img) => img.display_order === 2);
  TestValidator.equals(
    "second image is now at position 2",
    secondImageNow?.image_url,
    secondImageUrl,
  );
  // 10. Verify display_order sequence is correct (0, 1, 2)
  const displayOrders: number[] = reorderResponse.data
    .map((img) => img.display_order)
    .sort();
  TestValidator.equals(
    "display_order sequence is 0, 1, 2",
    displayOrders,
    [0, 1, 2],
  );
  // 11. Verify all images still exist with correct IDs
  const reorderedIds: string[] = reorderResponse.data
    .map((img) => img.id)
    .sort();
  const expectedIds: string[] = images
    .map((img) => img.id)
    .slice()
    .sort();
  TestValidator.equals(
    "all images exist after reorder",
    reorderedIds,
    expectedIds,
  );
  // 12. Verify each image has correct display_order in sequence
  reorderResponse.data.forEach((img, index) => {
    const expectedOrder: number = index;
    TestValidator.equals(
      `image at position ${index} has correct display_order`,
      img.display_order,
      expectedOrder,
    );
  });
  // 13. Verify product images are updated with new order
  TestValidator.equals(
    "product has correct image count",
    product.images.length,
    3,
  );
  // 14. Verify all image IDs in product match reorder response
  const productImageIds: string[] = product.images.map((img) => img.id).sort();
  TestValidator.equals(
    "product image IDs match reorder response",
    productImageIds,
    reorderedIds,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

export async function test_api_category_tree_browsing(
  connection: api.IConnection,
): Promise<void> {
  // 1. Call the public endpoint without authentication
  const tree: IEcommerceMallCategory.ITree =
    await api.functional.ecommerceMall.categories.tree(connection);
  typia.assert(tree);
  // 2. Validate root category exists with required fields
  TestValidator.predicate(
    "root category has id",
    tree.id !== undefined && tree.id !== null,
  );
  TestValidator.predicate(
    "root category has name",
    tree.name !== undefined && tree.name !== null,
  );
  TestValidator.predicate(
    "root category has slug",
    tree.slug !== undefined && tree.slug !== null,
  );
  TestValidator.predicate(
    "root category has display_order",
    typeof tree.display_order === "number",
  );
  // 3. Validate root category has children array
  TestValidator.predicate(
    "root category has children array",
    Array.isArray(tree.children),
  );
  // 4. Validate at least one root category exists
  TestValidator.predicate(
    "root category children count > 0",
    tree.children.length > 0,
  );
  // 5. Validate each subcategory (children of root)
  for (const subcategory of tree.children) {
    typia.assert(subcategory);
    // Subcategory required fields
    TestValidator.predicate(
      "subcategory has id",
      subcategory.id !== undefined && subcategory.id !== null,
    );
    TestValidator.predicate(
      "subcategory has name",
      subcategory.name !== undefined && subcategory.name !== null,
    );
    TestValidator.predicate(
      "subcategory has slug",
      subcategory.slug !== undefined && subcategory.slug !== null,
    );
    TestValidator.predicate(
      "subcategory has display_order",
      typeof subcategory.display_order === "number",
    );
    // One-level nesting limit: subcategories must have empty children array
    TestValidator.predicate(
      "subcategory has empty children array (one-level nesting limit)",
      Array.isArray(subcategory.children) && subcategory.children.length === 0,
    );
  }
  // 6. Validate root categories are sorted by display_order ASC
  if (tree.children.length > 1) {
    for (let i = 1; i < tree.children.length; i++) {
      const prevOrder = tree.children[i - 1].display_order;
      const currOrder = tree.children[i].display_order;
      TestValidator.predicate(
        "subcategories sorted by display_order ASC",
        currOrder >= prevOrder,
      );
    }
  }
  // 7. Validate display_order is non-negative for all categories
  TestValidator.predicate(
    "root category display_order non-negative",
    tree.display_order >= 0,
  );
  for (const subcategory of tree.children) {
    TestValidator.predicate(
      "subcategory display_order non-negative",
      subcategory.display_order >= 0,
    );
  }
  // 8. Validate UUID format for category IDs using pattern
  const uuidPattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  TestValidator.predicate(
    "root category id is valid UUID",
    uuidPattern.test(tree.id),
  );
  for (const subcategory of tree.children) {
    TestValidator.predicate(
      "subcategory id is valid UUID",
      uuidPattern.test(subcategory.id),
    );
  }
  // 9. Validate optional fields can be present (description, icon_uri)
  for (const subcategory of tree.children) {
    // description should be string | null | undefined or undefined
    if (subcategory.description !== undefined) {
      TestValidator.predicate(
        "subcategory description is string or null",
        typeof subcategory.description === "string" ||
          subcategory.description === null,
      );
    }
    // icon_uri should be string | null | undefined or undefined
    if (subcategory.icon_uri !== undefined) {
      TestValidator.predicate(
        "subcategory icon_uri is string or null",
        typeof subcategory.icon_uri === "string" ||
          subcategory.icon_uri === null,
      );
    }
  }
  // 10. Validate timestamps are ISO 8601 format if present
  if (tree.created_at !== undefined) {
    TestValidator.predicate(
      "root category created_at is valid date-time",
      !isNaN(Date.parse(tree.created_at)),
    );
  }
  if (tree.updated_at !== undefined) {
    TestValidator.predicate(
      "root category updated_at is valid date-time",
      !isNaN(Date.parse(tree.updated_at)),
    );
  }
  for (const subcategory of tree.children) {
    if (subcategory.created_at !== undefined) {
      TestValidator.predicate(
        "subcategory created_at is valid date-time",
        !isNaN(Date.parse(subcategory.created_at)),
      );
    }
    if (subcategory.updated_at !== undefined) {
      TestValidator.predicate(
        "subcategory updated_at is valid date-time",
        !isNaN(Date.parse(subcategory.updated_at)),
      );
    }
  }
}

