export async function test_api_admin_activity_aggregation_basic(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - use utility function instead of SDK
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  typia.assert(admin);
  // 2. Create new connection with admin token for subsequent requests
  const adminAuthorizedConnection: api.IConnection = {
    host: connection.host,
    headers: { Authorization: admin.token.access },
  };
  // 3. Test aggregation endpoint with basic pagination and grouping
  const requestBody = {
    page: 1,
    limit: 10,
    group_by: ["actor_type", "entity_type", "action_type"] as const,
    actor_types: ["customer", "seller", "admin"] as const,
    sort_by: "count",
    sort_order: "desc" as const,
  } satisfies IEcommerceMallActivityAggregation.IRequest;
  const result =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminAuthorizedConnection,
      { body: requestBody },
    );
  typia.assert(result);
  // 4. Validate response structure
  typia.assert(result.pagination);
  typia.assert(result.data);
  // 5. Verify pagination metadata
  TestValidator.equals("current page is 1", result.pagination.current, 1);
  TestValidator.equals("limit is 10", result.pagination.limit, 10);
  TestValidator.predicate(
    "records is positive",
    result.pagination.records >= 0,
  );
  TestValidator.predicate("pages is positive", result.pagination.pages >= 0);
  // 6. Verify each aggregation summary in data array
  for (const summary of result.data) {
    typia.assert(summary);
    // Validate summary structure
    TestValidator.predicate(
      "actor_type is not empty",
      summary.actor_type.length > 0,
    );
    TestValidator.predicate(
      "entity_type is not empty",
      summary.entity_type.length > 0,
    );
    TestValidator.predicate(
      "action_type is not empty",
      summary.action_type.length > 0,
    );
    // Validate count is positive integer
    TestValidator.predicate("count is positive", summary.count > 0);
    // Validate created_at is valid date-time format
    const parsedDate = new Date(summary.created_at);
    TestValidator.predicate(
      "created_at is valid date",
      !isNaN(parsedDate.getTime()),
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallActivityAggregation } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallActivityAggregation";
import type { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEcommerceMallActivityAggregation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallActivityAggregation";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

export async function test_api_admin_activity_aggregation_with_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup admin account
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Test with no filters (get all activities)
  const allAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(allAggregation);
  TestValidator.predicate(
    "all aggregation has pagination",
    allAggregation.pagination !== undefined,
  );
  // 3. Test with actor_types filter (only customer activities)
  const customerFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          actor_types: ["customer"] satisfies (
            | "customer"
            | "seller"
            | "admin"
            | "super_admin"
          )[],
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(customerFilter);
  TestValidator.predicate(
    "customer filter has pagination",
    customerFilter.pagination !== undefined,
  );
  // 4. Test with entity_types filter (only order activities)
  const orderFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          entity_types: [
            "order",
            "product",
            "review",
            "shipment",
          ] satisfies string[],
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(orderFilter);
  TestValidator.predicate(
    "order filter has pagination",
    orderFilter.pagination !== undefined,
  );
  // 5. Test with action_types filter (only created activities)
  const createdFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          action_types: [
            "created",
            "updated",
            "deleted",
            "approved",
            "rejected",
          ] satisfies string[],
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(createdFilter);
  TestValidator.predicate(
    "created filter has pagination",
    createdFilter.pagination !== undefined,
  );
  // 6. Test with date range filter
  const now = new Date();
  const fromDate = new Date(
    now.getTime() - 1000 * 60 * 60 * 24 * 30,
  ).toISOString() satisfies string & tags.Format<"date-time">;
  const toDate = new Date(
    now.getTime() + 1000 * 60 * 60 * 24,
  ).toISOString() satisfies string & tags.Format<"date-time">;
  const dateFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          from: fromDate,
          to: toDate,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(dateFilter);
  TestValidator.predicate(
    "date filter has pagination",
    dateFilter.pagination !== undefined,
  );
  // 7. Test with multiple filters combined
  const combinedFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          actor_types: ["customer", "seller"] satisfies (
            | "customer"
            | "seller"
            | "admin"
            | "super_admin"
          )[],
          entity_types: ["order", "product"] satisfies string[],
          action_types: ["created", "updated"] satisfies string[],
          from: fromDate,
          to: toDate,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(combinedFilter);
  TestValidator.predicate(
    "combined filter has pagination",
    combinedFilter.pagination !== undefined,
  );
  // 8. Test with group_by dimension
  const groupedFilter =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
          group_by: ["actor_type", "entity_type", "action_type"] satisfies (
            | "actor_type"
            | "entity_type"
            | "action_type"
            | "date"
          )[],
          sort_by: "count" satisfies
            | "count"
            | "actor_type"
            | "entity_type"
            | "action_type"
            | "date",
          sort_order: "desc" satisfies "asc" | "desc",
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(groupedFilter);
  TestValidator.predicate(
    "grouped filter has pagination",
    groupedFilter.pagination !== undefined,
  );
  // 9. Verify data structure in aggregation results
  for (const item of allAggregation.data) {
    typia.assert(item);
    TestValidator.predicate(
      "item actor_type is string",
      typeof item.actor_type === "string",
    );
    TestValidator.predicate(
      "item entity_type is string",
      typeof item.entity_type === "string",
    );
    TestValidator.predicate(
      "item action_type is string",
      typeof item.action_type === "string",
    );
    TestValidator.predicate("item count is at least 1", item.count >= 1);
    TestValidator.predicate(
      "item created_at is string",
      typeof item.created_at === "string",
    );
  }
  // 10. Verify pagination metadata structure
  TestValidator.predicate(
    "pagination current is non-negative",
    allAggregation.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative",
    allAggregation.pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    allAggregation.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    allAggregation.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "pagination pages calculation correct",
    allAggregation.pagination.pages ===
      Math.ceil(
        allAggregation.pagination.records / allAggregation.pagination.limit,
      ),
  );
  // 11. Verify filtering affects counts
  if (
    allAggregation.pagination.records > 0 &&
    customerFilter.pagination.records > 0
  ) {
    // Customer filter should return subset of all activities
    TestValidator.predicate(
      "customer count <= total count",
      customerFilter.pagination.records <= allAggregation.pagination.records,
    );
  }
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallActivityAggregation } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallActivityAggregation";
import type { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIEcommerceMallActivityAggregation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallActivityAggregation";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test admin's ability to customize aggregation grouping and sorting for activity oversight.
 *
 * Tests different grouping dimensions (actor_type, entity_type, action_type, date)
 * and sorting options (count asc/desc, actor_type, entity_type, action_type, date)
 * to validate activity trend analysis capabilities.
 */
export async function test_api_admin_activity_aggregation_grouping_and_sorting(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create authenticated admin session
  const adminConnection: api.IConnection = { host: connection.host };
  const admin: IEcommerceMallAdmin.IAuthorized = await authorize_admin_join(
    adminConnection,
    {},
  );
  typia.assert(admin);
  // 2. Test grouping by actor_type
  const actorTypeAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["actor_type"] as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(actorTypeAggregation);
  // Validate actor_type grouping results
  TestValidator.equals(
    "actor_type aggregation has pagination",
    actorTypeAggregation.pagination.current,
    1,
  );
  TestValidator.equals(
    "actor_type aggregation has limit",
    actorTypeAggregation.pagination.limit,
    100,
  );
  if (actorTypeAggregation.data.length > 0) {
    const firstActorType = actorTypeAggregation.data[0];
    TestValidator.predicate(
      "actor_type aggregation has valid actor_type",
      ["customer", "seller", "admin", "super_admin"].includes(
        firstActorType.actor_type,
      ),
    );
    TestValidator.predicate(
      "actor_type count is valid",
      firstActorType.count >= 1,
    );
  }
  // 3. Test grouping by entity_type
  const entityTypeAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["entity_type"] as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(entityTypeAggregation);
  if (entityTypeAggregation.data.length > 0) {
    const firstEntityType = entityTypeAggregation.data[0];
    TestValidator.predicate(
      "entity_type aggregation has valid count",
      firstEntityType.count >= 1,
    );
  }
  // 4. Test grouping by action_type
  const actionTypeAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["action_type"] as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(actionTypeAggregation);
  if (actionTypeAggregation.data.length > 0) {
    const firstActionType = actionTypeAggregation.data[0];
    TestValidator.predicate(
      "action_type aggregation has valid count",
      firstActionType.count >= 1,
    );
  }
  // 5. Test grouping by date
  const dateAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["date"] as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(dateAggregation);
  if (dateAggregation.data.length > 0) {
    const firstDate = dateAggregation.data[0];
    TestValidator.predicate(
      "date aggregation has valid count",
      firstDate.count >= 1,
    );
  }
  // 6. Test grouping by multiple dimensions (actor_type, entity_type)
  const multiDimensionAggregation =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["actor_type", "entity_type"] as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(multiDimensionAggregation);
  if (multiDimensionAggregation.data.length > 0) {
    const firstMulti = multiDimensionAggregation.data[0];
    TestValidator.predicate(
      "multi-dimension has actor_type",
      firstMulti.actor_type !== "",
    );
    TestValidator.predicate(
      "multi-dimension has entity_type",
      firstMulti.entity_type !== "",
    );
    TestValidator.predicate(
      "multi-dimension has valid count",
      firstMulti.count >= 1,
    );
  }
  // 7. Test sorting by count (descending) - most frequent activities first
  const sortCountDesc =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
          group_by: ["actor_type"] as const,
          sort_by: "count",
          sort_order: "desc" as const,
        } satisfies IEcommerceMallActivityAggregation.IRequest,
      },
    );
  typia.assert(sortCountDesc);
  // Validate descending count sort
  if (sortCountDesc.data.length >= 2) {
    const firstCount = sortCountDesc.data[0].count;
    const secondCount = sortCountDesc.data[1].count;
    TestValidator.predicate(
      "count desc sort has highest first",
      firstCount >= secondCount,
    );
  }
  // 8. Test sorting by count (ascending) - least frequent activities first
  const sortCountAsc =
    await api.functional.ecommerceMall.admin.activity.aggregation.index(
      adminConnection,
      {
        body: {
