      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
      values:
        [] as Prisma.ecommerce_mall_platform_configuration_valuesCreateNestedManyWithoutConfigurationInput,
    } satisfies Prisma.ecommerce_mall_platform_configurationsCreateInput;
  }
}

import { IEcommerceMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallShipment";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { Prisma } from "@prisma/sdk";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";

export namespace EcommerceMallShipmentCollector {
  export async function collect(props: {
    body: IEcommerceMallShipment.ICreate;
    ecommerceMallSellers: IEntity;
  }) {
    const id: string = v4();
    // Query first order item to derive the order
    const firstOrderItem =
      await MyGlobal.prisma.ecommerce_mall_order_items.findFirstOrThrow({
        where: { id: props.body.order_item_ids[0] },
      });
    return {
      // Scalar fields
      id,
      carrier_name: props.body.carrier_name,
      carrier_phone: props.body.carrier_phone ?? null,
      carrier_website: props.body.carrier_website ?? null,
      status: "pending",
      shipped_at: null,
      delivered_at: null,
      estimated_delivery_at: null,
      delivery_address: props.body.delivery_address ?? null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
      // BelongsTo relations
      order: { connect: { id: firstOrderItem.ecommerce_mall_order_id } },
      seller: { connect: { id: props.ecommerceMallSellers.id } },
      // HasMany relations (orderItems—order items already exist, just link them)
      orderItems: {
        connect: props.body.order_item_ids.map((itemId) => ({ id: itemId })),
      },
    } satisfies Prisma.ecommerce_mall_shipmentsCreateInput;
  }
}

import { IEcommerceMallCancellationRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCancellationRequest";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { Prisma } from "@prisma/sdk";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";

export namespace EcommerceMallCancellationRequestCollector {
  export async function collect(props: {
    body: IEcommerceMallCancellationRequest.ICreate;
    ecommerceMallCustomers: IEntity;
  }) {
    const id: string = v4();
    // Query order_item to get seller_snapshot_id for the seller relation
    const orderItem =
      await MyGlobal.prisma.ecommerce_mall_order_items.findFirstOrThrow({
        where: { id: props.body.order_item_id },
        select: {
          seller_snapshot_id: true,
        },
      });
    return {
      id,
      orderItem: {
        connect: { id: props.body.order_item_id },
      },
      customer: {
        connect: { id: props.ecommerceMallCustomers.id },
      },
      seller: {
        connect: { id: orderItem.seller_snapshot_id },
      },
      inventoryRecords: undefined,
      snapshots: undefined,
      status: "pending",
      reason: props.body.reason,
      seller_response: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      deleted_at: null,
    } satisfies Prisma.ecommerce_mall_cancellation_requestsCreateInput;
  }
}

import { IEcommerceMallInventoryRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallInventoryRecord";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { Prisma } from "@prisma/sdk";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";

export namespace EcommerceMallInventoryRecordCollector {
  export async function collect(props: {
    body: IEcommerceMallInventoryRecord.ICreate;
    ecommerceMallSellers: IEntity;
  }) {
    const id: string = v4();
    const created_at: Date = new Date();
    // Query variant to get current inventory level for remaining_quantity calculation
    const variant =
      await MyGlobal.prisma.ecommerce_mall_product_variants.findFirstOrThrow({
        where: { id: props.body.ecommerce_mall_product_variant_id },
        select: {
          stock_quantity: true,
          reserved_quantity: true,
        },
      });
    const remaining_quantity: number =
      variant.stock_quantity -
      variant.reserved_quantity +
      props.body.quantity_change;
    return {
      id,
      quantity_change: props.body.quantity_change,
      remaining_quantity,
      reason: props.body.reason,
      type: props.body.type,
      description: props.body.description ?? null,
      created_at: created_at.toISOString(),
      updated_at: created_at.toISOString(),
      deleted_at: null,
      variant: {
        connect: { id: props.body.ecommerce_mall_product_variant_id },
      },
      order: undefined,
      cancellationRequest: undefined,
      refundRequest: undefined,
      snapshots: { create: [] },
    } satisfies Prisma.ecommerce_mall_inventory_recordsCreateInput;
  }
}

