    return {
      select: {
        id: true,
        configuration_key: true,
        description: true,
        configuration_type: true,
        scope: true,
        default_value: true,
        is_active: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        values: {
          select: {
            value: true,
            environment_scope: true,
          },
        } satisfies Prisma.ecommerce_mall_platform_configuration_valuesFindManyArgs,
