export namespace EcommerceMallProductVariantAtUpdateOptionTransformer {
  export type Payload = Prisma.ecommerce_mall_product_variant_optionsGetPayload<
    ReturnType<typeof select>
  >;
  export function select() {
    return {
      select: {
        id: true,
        key: true,
        value: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        productVariant:
          EcommerceMallProductVariantAtUpdateOptionAddTransformer.select(),
      },
    } satisfies Prisma.ecommerce_mall_product_variant_optionsFindManyArgs;
  }
  export async function transform(
    input: Payload,
  ): Promise<IEcommerceMallProductVariant.IUpdateOption> {
    const operations: (
      | IEcommerceMallProductVariant.IUpdateOptionAdd
      | IEcommerceMallProductVariant.IUpdateOptionUpdate
      | IEcommerceMallProductVariant.IUpdateOptionRemove
    )[] = [];
    if (input.key && input.value && input.deleted_at === null) {
      operations.push({
        action: "add",
        key: input.key,
        value: input.value,
      });
    }
    if (input.key && input.value) {
      operations.push({
        action: "update",
        key: input.key,
        value: input.value,
      });
    }
    if (input.key && input.deleted_at) {
      operations.push({
        action: "remove",
        key: input.key,
      });
    }
    return {
      operations,
    };
  }
}

