        case "update": {
          await tx.ecommerce_mall_product_variant_options.update({
            where: {
              product_variant_id_key: {
                product_variant_id: variantId,
                key: operation.key,
              },
              deleted_at: null,
            },
            data: {
              value: operation.value,
              updated_at: new Date(),
            },
          });
          break;
        }
        case "remove": {
          await tx.ecommerce_mall_product_variant_options.update({
            where: {
              product_variant_id_key: {
                product_variant_id: variantId,
                key: operation.key,
              },
              deleted_at: null,
            },
            data: {
              deleted_at: new Date(),
            },
          });
          break;
        }
      }
    }
  });
  const variantOptions =
    await MyGlobal.prisma.ecommerce_mall_product_variant_options.findMany({
      where: {
        product_variant_id: variantId,
        deleted_at: null,
      },
      select: {
        id: true,
        key: true,
        value: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        product_variant_id: true,
      },
    });
  const optionsMap = variantOptions.reduce<{
    [key: string]: string;
  }>((acc, option) => {
    acc[option.key] = option.value;
    return acc;
  }, {});
  const updatedVariant =
    await MyGlobal.prisma.ecommerce_mall_product_variants.update({
      where: {
        id: variantId,
      },
      data: {
        options: JSON.stringify(optionsMap),
        updated_at: new Date(),
