      select: {
        id: true,
        sku: true,
        options: true,
        base_price: true,
        sale_price: true,
        stock_quantity: true,
        reserved_quantity: true,
        status: true,
        sort_order: true,
        is_default: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
