export async function postEcommerceMallAuthSuperAdminRefresh(props: {
  body: IEcommerceMallSuperAdmin.IRefresh;
}): Promise<IEcommerceMallSuperAdmin.IAuthorized> {
  const refresh_token = props.body.refresh_token;
  let decoded: {
    type: string;
    id: string;
    session_id: string;
    created_at: string;
  };
  try {
    decoded = jwt.verify(refresh_token, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as {
      type: string;
      id: string;
      session_id: string;
      created_at: string;
    };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "super_admin") {
    throw new HttpException("Invalid token type", 403);
  }
  const session =
    await MyGlobal.prisma.ecommerce_mall_super_admin_sessions.findFirst({
      where: {
        id: decoded.session_id,
        super_admin_id: decoded.id,
      },
    });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  const super_admin =
    await MyGlobal.prisma.ecommerce_mall_super_admins.findUniqueOrThrow({
      where: { id: decoded.id },
      select: {
        id: true,
        email: true,
        full_name: true,
        display_name: true,
        grade: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
  if (super_admin.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const access_token = jwt.sign(
    {
      type: "super_admin",
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const new_refresh_token = jwt.sign(
    {
      type: "super_admin",
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  await MyGlobal.prisma.ecommerce_mall_super_admin_sessions.update({
    where: { id: decoded.session_id },
    data: {
      expired_at: refreshExpires,
      updated_at: new Date(),
    },
  });
  return {
    id: super_admin.id as string & tags.Format<"uuid">,
    email: super_admin.email,
    fullName: super_admin.full_name,
    displayName: super_admin.display_name,
    grade: super_admin.grade as number & tags.Type<"int32">,
    status: super_admin.status,
    createdAt: super_admin.created_at.toISOString(),
    updatedAt: super_admin.updated_at.toISOString(),
    deletedAt: super_admin.deleted_at?.toISOString() ?? null,
    access: access_token,
    refresh: new_refresh_token,
    expired_at: accessExpires.toISOString(),
    token: {
      access: access_token,
      refresh: new_refresh_token,
      expired_at: accessExpires.toISOString(),
      refreshable_until: refreshExpires.toISOString(),
    },
  } satisfies IEcommerceMallSuperAdmin.IAuthorized;
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteEcommerceMallSellerProductsProductId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
}): Promise<void> {
  const product = await MyGlobal.prisma.ecommerce_mall_products.findUnique({
    where: { id: props.productId },
  });
  if (product === null) {
    throw new HttpException("Product not found", 404);
  }
  if (product.seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }
  if (product.deleted_at !== null) {
    throw new HttpException("Product already deleted", 409);
  }
  const variantIds = await MyGlobal.prisma.ecommerce_mall_product_variants
    .findMany({
      where: { product_id: props.productId },
      select: { id: true },
    })
    .then((v) => v.map((x) => x.id));
  if (variantIds.length === 0) {
    await MyGlobal.prisma.ecommerce_mall_products.delete({
      where: { id: props.productId },
    });
    return;
  }
  const orderItemCount =
    await MyGlobal.prisma.ecommerce_mall_order_items.groupBy({
      by: ["variant_snapshot_id"],
      where: {
        variant_snapshot_id: {
          in: variantIds,
        },
      },
      _count: true,
    });
  if (orderItemCount.some((c: { _count: number }) => c._count > 0)) {
    throw new HttpException(
      "Cannot delete product with paid or shipped order items",
      409,
    );
  }
  const cancellationCount =
    await MyGlobal.prisma.ecommerce_mall_cancellation_requests.groupBy({
      by: ["order_item_id"],
      where: {
        order_item_id: {
          in: await MyGlobal.prisma.ecommerce_mall_order_items
            .findMany({
              where: {
                variant_snapshot_id: {
                  in: variantIds,
                },
              },
              select: { id: true },
            })
            .then((x) => x.map((i) => i.id)),
        },
        status: {
          notIn: ["completed", "rejected"],
        },
      },
      _count: true,
    });
  if (cancellationCount.some((c: { _count: number }) => c._count > 0)) {
    throw new HttpException(
      "Cannot delete product with pending cancellation requests",
      409,
    );
  }
  const refundCount =
    await MyGlobal.prisma.ecommerce_mall_refund_requests.groupBy({
      by: ["ecommerce_mall_order_item_id"],
      where: {
        ecommerce_mall_order_item_id: {
          in: await MyGlobal.prisma.ecommerce_mall_order_items
            .findMany({
              where: {
                variant_snapshot_id: {
                  in: variantIds,
                },
              },
              select: { id: true },
            })
            .then((x) => x.map((i) => i.id)),
        },
        status: {
          notIn: ["completed", "rejected"],
        },
      },
      _count: true,
    });
  if (refundCount.some((c: { _count: number }) => c._count > 0)) {
    throw new HttpException(
      "Cannot delete product with pending refund requests",
      409,
    );
  }
  await MyGlobal.prisma.ecommerce_mall_products.delete({
    where: { id: props.productId },
  });
}

