}): Promise<IEcommerceMallInventoryRecord> {
  // Verify the product variant exists
  const variant =
    await MyGlobal.prisma.ecommerce_mall_product_variants.findFirst({
      where: {
        id: props.body.ecommerce_mall_product_variant_id,
        deleted_at: null,
