   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":configId")
  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("configId")
    configId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteEcommerceMallAdminPlatformConfigurationsConfigId({
        admin,
        configId,
      });
